head.script:
///////// 1. 변수 및 선언 영역 /////////
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

// alert('[InfoMenuID]'+InfoMenuID());
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.clickBzProcsNo;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSecugrpId;
scwin.gMktTpCd;
scwin.gAcptNo;
scwin.gAcptSeq;
scwin.gAcptNoListFee;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const parentWin = $c.lc.fn_GetRecvDocProvider();
        // var parentWin = frame.Provider("../");
        // alert('[parentWin]'+parentWin);
        if (scwin.gIsurCd !== "" && scwin.gIsurCd !== undefined) {
            txb_ISUR_CD.setValue(scwin.gIsurCd);
            txb_COM_NM.setValue(scwin.gComAbbrv);
            scwin.fr_SecuGrpId = scwin.gSecugrpId;
            scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
            $c.lic.fn_gridNameChange(scwin.fr_SecuGrpId);
            btn_Search.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            txb_ISUR_CD.focus();
            return;
        }
        await scwin.issListSync();
        dts_IssList.setRowPosition(dts_IssList.getRowCount(), 0);
        dts_IssRecv.setRowPosition(dts_IssRecv.getRowCount(), 0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            txb_ISUR_CD.focus();
            return;
        }
        $c.pre_newlisting.fn_OpenDetailCorpIsu(-9999);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30

        if (scwin.pMenuID === "STF05200") {
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        } else if (scwin.pMenuID === "STF05255") {
            // 기업인수목적 회사
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name grd_IssRecv_OnDblClick
 * @description grd_IssRecv 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssRecv_OnDblClick = function(row, colid) {
    try {
        scwin.openDetailExtr(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.grd_IssRecv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_IssList_OnDblClick
 * @description grd_IssList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssList_OnDblClick = function(row, colid) {
    try {
        $c.pre_newlisting.fn_OpenDetailCorpIsu(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.grd_IssList_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_IssList_OnLoadError
 * @description dts_IssList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IssList_OnLoadError = async function() {
    try {
        // var parentWin = frame.Provider("../frame_tail");
        // frame.Provider("../").frame_tail.vIsurCd;
        // alert('[frame_tail.vIsurCd]'+frame.Provider("../").frame_tail.vIsurCd);
        await $c.win.alert(dts_IssList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IssRecv_OnLoadError
 * @description dts_IssRecv 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IssRecv_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_IssRecv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssRecv_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IssRecv_OnLoadCompleted
 * @description dts_IssRecv 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssRecv_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_1.setValue("총 " + dts_IssRecv.getRowCount() + " 건");
        // dts_IssRecv.RowPosition = rowcount;
        // CloseWin(rowcount, grd_IsuRecv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssRecv_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_IssList_OnLoadCompleted
 * @description dts_IssList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssList_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_2.setValue("총 " + dts_IssList.getRowCount() + " 건");
        // dts_IssList.RowPosition = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setBzProcsNo = async function(obj) {
    scwin.clickBzProcsNo = dts_IssList.getCellData(Number(obj), "BZ_PROCS_NO");

    // 상장수수료로 인해 추가 TBLD_LIST_APPL_FORM 테이블에 접수번호가 없으면 SMS전송 버튼이 보이지 않음
    scwin.gAcptNoListFee = dts_IssList.getCellData(Number(obj), "ACPT_NO");

    const sbmOptions = {
        id : "sbm_dts_IssListAcptNo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_IssListAcptNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.gAcptNoListFee = dts_IssListAcptNo.getCellData(1, "ACPT_NO");

    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name issListSync
 * @description iss List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.issListSync = async function() {
    // var url = "/Listing.do?method=listStkIssListInfo&inputMessageId=LISTING_COMMON_INOUT";
    const sbmOptions = {
        id : "sbm_dts_IssList",
        action : "/Listing.do",
        ref : "",
        target : "dts_IssList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_IssRecv",
        action : "/Listing.do",
        ref : "",
        target : "dts_IssRecv=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        $c.lic.fn_gridNameChange(scwin.fr_SecuGrpId);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        btn_Search.trigger("onclick");
    }
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name openDetailExtr
 * @description open Detail Extr 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.openDetailExtr = function(row) {
    let secugrpId = scwin.fr_SecuGrpId;
    scwin.clickBzProcsNo = ""; // 초기화
    scwin.gAcptNo = dts_IssRecv.getCellData(row, "ACPT_NO");
    scwin.gAcptNoListFee = scwin.gAcptNo;
    // gAcptNo = "20080616007146";
    scwin.gAcptSeq = dts_IssRecv.getCellData(row, "BYACPTNO_SEQ");
    $c.lic.fn_OpenDetailIssMng(txb_ISUR_CD, scwin.fr_SecuGrpId, scwin.gAcptNo);
};

/**
 * @method
 * @name openDetailCorpIsu
 * @description 신규상장시 상장종목팝업창
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailCorpIsu = async function(row) {
    scwin.gAcptNo = ""; // 초기화

    scwin.gAcptSeq = ""; // 초기화
    scwin.gAcptNoListFee = "";
    let secugrpId = scwin.fr_SecuGrpId;
    if (row > 0) {
        // 그리드에서 선택시
        await scwin.setBzProcsNo(row);
    } else {
        // 신규버튼 선택시
        scwin.clickBzProcsNo = ""; // 초기화

    }

    /*
    		var selfWin = frame.Provider("./");
    		var nWidth = selfWin.Width;
    		var nHeight = selfWin.Height;
    		var targetWidth = 900;
    		var targetHeight = 790;
    		XPos = (nWidth / 2) - (targetWidth / 2);
    		YPos = (nHeight / 2) - (targetHeight / 2);
            //frame.CreateDialogFrame("ULDSTF92002","/listingcommon/ULDSTF92002.gfm", fn_getSecuGrpNm(secugrpId)+" 주식발행관리", XPos, YPos, targetWidth, targetHeight, "window");
    		frame.CreateDialogFrame("ULDSTF92002","/listingcommon/ULDSTF92002.gfm", fn_getSecuGrpNm(secugrpId)+" 주식발행관리", 10, 10, 10 20, "window");
     */
    $c.lic.fn_OpenDetailIssMng(txb_ISUR_CD, scwin.fr_SecuGrpId, scwin.clickBzProcsNo);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDSTF05200.xml", SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_IssList, {fileName: "주식발행내역", type: "8"});
};
